def core_section(soft=True):
    cards = ''.join(f'<div class="cx-card"><div class="cx-eyebrow">{k}</div><h3>{t}</h3><p>{p}</p></div>' for t, k, p in ITEMS)
    return f'''<section class="cx-sec{' cx-soft' if soft else ''}" id="core"><div class="cx-wrap">
<div class="cx-center"><div class="cx-eyebrow">{EYE}</div><h2>{H2}</h2><p class="cx-lead" style="max-width:860px">{SYN}</p></div>
<p style="max-width:860px;margin:22px auto 0;text-align:center">{INTRO}</p>
<div class="cx-grid cx-g3">{cards}</div>
<div class="cx-inst"><h3>{INST_H}</h3>{''.join('<p>' + x + '</p>' for x in INST)}</div>
</div></section>'''


